    INSERT INTO questions (course_id, question_text, question_type, correct_answer, explanation) VALUES
    (v_course_id, '___ is the study of conflict and cooperation by international actors.', 'fill_in_blank', 'International Relations', 'International Relations examines interactions between states and other international actors.'),
    (v_course_id, 'In the words of ______________ "international relations is that area of human action where Inescapable interdependence meets with inadequate control".', 'fill_in_blank', 'Karl Deutsch', 'Karl Deutsch emphasized the tension between interdependence and control in international relations.'),
    (v_course_id, 'The history of the present international system started in _______________ after the peace of Westphalia.', 'fill_in_blank', '1648', 'The Peace of Westphalia in 1648 established the modern state system.'),
    (v_course_id, 'The nature of the international system from the realists'' perspective is called ____', 'fill_in_blank', 'Anarchical', 'Realists view the international system as anarchical with no central authority.'),
    (v_course_id, 'Some scholars perceived International Relations as generalised picture of the ____', 'fill_in_blank', 'International Scene', 'IR provides a broad overview of global political interactions.'),
    (v_course_id, 'Dale Fuller''s definition of analysis of international relations states that it is a body of data systematised by a distinctive analytical method and capable of permitting _______ with exactitude', 'fill_in_blank', 'Predictions', 'Fuller emphasized the predictive capacity of systematic IR analysis.'),
    (v_course_id, 'The classical approach is also known as ____________________________', 'fill_in_blank', 'Traditional approach', 'Classical and traditional approaches refer to the same historical methodology in IR.'),
    (v_course_id, 'Morton Kaplan is an important proponent of the____', 'fill_in_blank', 'Scientific Approach', 'Kaplan contributed to the scientific/behavioral approach in international relations.'),
    (v_course_id, 'The prominent realists include the classical theorists Thomas Hobbes and _______', 'fill_in_blank', 'Niccolo Machiavelli', 'Machiavelli and Hobbes are foundational realist thinkers.'),
    (v_course_id, 'The Declarations of the American War of independence of 1776 and French revolution of ________________', 'fill_in_blank', '1789', 'The French Revolution began in 1789, following the American Revolution.'),
    (v_course_id, 'International relations is a broader and wider term that involves ________________', 'fill_in_blank', 'International Politics', 'International relations encompasses international politics and broader interactions.'),
    (v_course_id, '____ deals with body of customary and conventional rules considered legally binding by civilised states in their intercourse with each other', 'fill_in_blank', 'International law', 'International law governs relations between states through binding rules.'),
    (v_course_id, 'The present nation-state system emerged in ____.', 'fill_in_blank', '1648', 'The modern state system originated with the Peace of Westphalia in 1648.'),
    (v_course_id, '____ helps people to understand their place in society, and provides a program for social and political action.', 'fill_in_blank', 'Ideology', 'Ideology provides frameworks for understanding society and guiding action.'),
    (v_course_id, 'In general, political actors are classified into two which include, namely ____', 'fill_in_blank', 'State and non-state actors', 'International actors are broadly categorized into state and non-state entities.');
    INSERT INTO questions (course_id, question_text, question_type, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
    (v_course_id, 'According to Morgenthau, the most stable factor upon which the power of a nation depends is called ____', 'multiple_choice', 'Economy', 'Geography', 'Military', 'Population', 'B', 'Morgenthau considered geography the most stable element of national power.'),
    (v_course_id, 'A nation population is a major element of its______', 'multiple_choice', 'Power', 'Culture', 'Economy', 'Politics', 'A', 'Population size and quality contribute significantly to national power.'),
    (v_course_id, '____ It is the ability to get what you want through attraction rather than coercion or payments', 'multiple_choice', 'Hard power', 'Soft power', 'Smart power', 'Economic power', 'B', 'Soft power relies on attraction and persuasion rather than force.'),
    (v_course_id, '____is a sets of governing arrangements that includes networks of rules, norms, and procedures that regularise behaviour and control its effects.', 'multiple_choice', 'Regime', 'Government', 'Organization', 'Alliance', 'A', 'International regimes establish rules and norms for state behavior.'),
    (v_course_id, '____employs threat or limited force to persuade an opponent to call off or undo an encroachment', 'multiple_choice', 'Deterrence', 'Coercive diplomacy', 'Compellence', 'Preemption', 'B', 'Coercive diplomacy uses threats to change opponent behavior.'),
    (v_course_id, '____ of analysis focuses on the actions, behaviour, attitudes, idiosyncrasies or psychology of individual policymakers', 'multiple_choice', 'State level', 'Individual level', 'Systemic level', 'International level', 'B', 'Individual level analysis examines characteristics of decision-makers.'),
    (v_course_id, 'General System theory was first formulated by Ludwig von Bertalanfy as an explanatory paradigm in ____', 'multiple_choice', 'Physics', 'Biology', 'Economics', 'Psychology', 'B', 'Bertalanfy developed system theory initially in biological sciences.'),
    (v_course_id, 'Systems theory deals with the relationships between ____', 'multiple_choice', 'States', 'Variables', 'Actors', 'Theories', 'B', 'Systems theory examines relationships between variables within systems.'),
    (v_course_id, 'Game theory was developed by mathematician''s and____ who were particularly concerned with political phenomena.', 'multiple_choice', 'Sociologists', 'Economists', 'Psychologists', 'Historians', 'B', 'Economists and mathematicians collaboratively developed game theory.'),
    (v_course_id, 'A second strategy would be to choose one of the ____routes', 'multiple_choice', 'Primary', 'Alternative', 'Direct', 'Indirect', 'B', 'Strategic choices involve selecting among alternative courses of action.'),
    (v_course_id, 'The issue of strategy is concerned with choices from among alternative actions rather than with _______end states', 'multiple_choice', 'Desired', 'Alternative', 'Final', 'Ideal', 'B', 'Strategy focuses on means rather than ultimate ends.'),
    (v_course_id, 'International relations theorist have developed a number of game parameters among which are ____ and the n-person non-zero-sum game', 'multiple_choice', 'Zero-sum-game', 'Positive-sum-game', 'Negative-sum-game', 'Mixed-game', 'A', 'Zero-sum games are fundamental models in international relations theory.'),
    (v_course_id, 'Every game has a full structure of ____', 'multiple_choice', 'Rules', 'Information', 'Players', 'Outcomes', 'B', 'Information structure is essential to game theoretical analysis.'),
    (v_course_id, '____ requires choosing among all the assembled alternative option with the best prospect of achieving the desired goal.', 'multiple_choice', 'Decision', 'Choice', 'Selection', 'Option', 'B', 'Strategic choice involves selecting the most promising alternative.'),
    (v_course_id, 'At the end of the Cold War in____, the international community experienced a lot of optimism', 'multiple_choice', '1989', '1990', '1991', '1992', 'B', 'The Cold War effectively ended around 1990 with major geopolitical shifts.'),
    (v_course_id, '________________ policy is the system of activities evolved by communities for changing the behaviour of other states and for adjusting their own activities to the international environment', 'multiple_choice', 'Domestic', 'Foreign', 'Economic', 'Security', 'B', 'Foreign policy involves managing external relations and adaptations.'),
    (v_course_id, 'The father of the modern theory of sovereignty was the 16th-century French political thinker was called _____________', 'multiple_choice', 'Jean Bodin', 'Thomas Hobbes', 'John Locke', 'Montesquieu', 'A', 'Jean Bodin developed the modern concept of state sovereignty.'),
    (v_course_id, '__________________ is very vital in maintaining peace and stability within the international relations', 'multiple_choice', 'Balance of power', 'Collective security', 'International law', 'Diplomacy', 'A', 'Balance of power helps prevent any single state from dominating others.'),
    (v_course_id, '______ refer to the general long-term and discontinuing purpose which the state, the nation, and the government all see themselves as serving', 'multiple_choice', 'National goals', 'National Interest', 'State objectives', 'Government aims', 'B', 'National interest represents fundamental state purposes and objectives.'),
    (v_course_id, 'Primary interests of any country include the preservation of political, physical and _______________ identity of the state', 'multiple_choice', 'Economic', 'Cultural', 'Social', 'Military', 'B', 'Cultural identity preservation is a core national interest.'),
    (v_course_id, 'Non-aligned movement traces its origins to the ___________ Conference', 'multiple_choice', 'Bandung', 'Belgrade', 'Cairo', 'Jakarta', 'A', 'The 1955 Bandung Conference laid foundations for the Non-Aligned Movement.'),
    (v_course_id, '______massacre between Tutsis and Hutus resulted in the deaths of 800,000 people in April 1994', 'multiple_choice', 'Burundi', 'Rwanda', 'Congo', 'Uganda', 'B', 'The Rwandan genocide resulted in approximately 800,000 deaths.'),
    (v_course_id, 'In _____ interim Prime Minister, Jawaharlal Nehru announced a policy that eventually metamorphosed into non-alignment', 'multiple_choice', '1946', '1947', '1948', '1949', 'B', 'Nehru announced non-alignment principles in 1947 after Indian independence.'),
    (v_course_id, 'Monrovia is the capital of ___________', 'multiple_choice', 'Liberia', 'Ghana', 'Nigeria', 'Senegal', 'A', 'Monrovia is the capital city of Liberia.'),
    (v_course_id, 'Bamako is the capital of _______', 'multiple_choice', 'Mali', 'Niger', 'Chad', 'Burkina Faso', 'A', 'Bamako serves as the capital of Mali.'),
    (v_course_id, 'On 7th August, Yasir Arafat proposed a ______ point peace plan to address the Palestine question', 'multiple_choice', 'Three', 'Four', 'Five', 'Six', 'B', 'Arafat proposed a four-point peace plan for Palestinian-Israeli conflict.'),
    (v_course_id, 'Foreign policy ______ involves studying or measuring the direction and intensity of interaction of nation-states', 'multiple_choice', 'Formulation', 'Analysis', 'Implementation', 'Evaluation', 'B', 'Foreign policy analysis examines patterns and intensity of state interactions.'),
    (v_course_id, 'The future of state affairs can simply be referred to as _________', 'multiple_choice', 'Foreign policy goals', 'Foreign policy objectives', 'National interests', 'State priorities', 'B', 'Foreign policy objectives represent future-oriented state intentions.'),
    (v_course_id, 'Economy as put forward by Hans Morgenthau can be classified as element of state ______', 'multiple_choice', 'Wealth', 'Power', 'Influence', 'Security', 'B', 'Morgenthau considered economic capacity as an element of national power.'),
    (v_course_id, 'Long-range goals deal with plans, visions, and _______________', 'multiple_choice', 'Strategies', 'Dreams', 'Policies', 'Programs', 'B', 'Long-range foreign policy goals involve visionary aspirations.'),
    (v_course_id, 'Foreign policy objectives are derived from both ____ and ____ sources', 'multiple_choice', 'political and economic', 'internal and external', 'domestic and international', 'military and diplomatic', 'B', 'Foreign policy draws from both domestic and international factors.'),
    (v_course_id, '____________________ entailed full participation in free international trade and access to world markets while avoiding foreign conflicts', 'multiple_choice', 'Military expansion', 'Commercial Expansion', 'Political expansion', 'Cultural expansion', 'B', 'Commercial expansion focuses on economic integration while avoiding conflicts.'),
    (v_course_id, 'During the invasion of Kuwait, it took just ______ hours, for all of Kuwait to fall under Iraqi control', 'multiple_choice', '12', '24', '48', '72', 'A', 'Iraq''s 1990 invasion of Kuwait was completed within approximately 12 hours.'),
    (v_course_id, '______________ is the first country in Africa to gain independence in 1847', 'multiple_choice', 'Ghana', 'Liberia', 'Ethiopia', 'Egypt', 'B', 'Liberia declared independence in 1847, though Ethiopia maintained independence.'),
    (v_course_id, 'Panama is among the countries of the world once invaded by the _______', 'multiple_choice', 'Soviet Union', 'United States of America', 'United Kingdom', 'France', 'B', 'The US invaded Panama in 1989 during Operation Just Cause.'),
    (v_course_id, 'The most important actors in International Relation are _____', 'multiple_choice', 'NGOs', 'States', 'Corporations', 'International Organizations', 'B', 'States remain the primary actors in traditional international relations.'),
    (v_course_id, 'The nature of the international system from the____ perspective is anarchical', 'multiple_choice', 'Liberalists''', 'Realists''', 'Constructivists''', 'Marxists''', 'B', 'Realists characterize the international system as fundamentally anarchical.'),
    (v_course_id, 'The perpetual existence of conflict among nations is one of the assumptions of ___', 'multiple_choice', 'Liberal Approach', 'Realist Approach', 'Constructivist Approach', 'Critical Approach', 'B', 'Realism assumes conflict is inherent in international relations.'),
    (v_course_id, 'International law is an aspect of international relations that moderates, regulates and ___ the relationships between states in the international system.', 'multiple_choice', 'Controls', 'Dictates', 'Eliminates', 'Simplifies', 'A', 'International law controls and regulates state interactions.'),
    (v_course_id, '__________________ is one of the sources of International Law', 'multiple_choice', 'National constitutions', 'Treaties', 'Domestic laws', 'Political speeches', 'B', 'Treaties are formal sources of international law.'),
    (v_course_id, 'In playing its role___ provide mechanisms for cross-border interactions, and also shape the values and goals these interactions are pursuing.', 'multiple_choice', 'Domestic politics', 'International Law', 'Military alliances', 'Economic systems', 'B', 'International law facilitates and shapes cross-border interactions.'),
    (v_course_id, 'As a source of power____ is largely a phenomenon of totalitarian states', 'multiple_choice', 'Economy', 'Ideology', 'Military', 'Diplomacy', 'B', 'Ideology serves as a power source particularly in totalitarian regimes.'),
    (v_course_id, '_________________ is the ability to get what you want through attraction rather than coercion or payments.', 'multiple_choice', 'Hard power', 'Soft power', 'Economic power', 'Military power', 'B', 'Soft power relies on attraction and cultural influence.'),
    (v_course_id, 'Which of the following is not the source of international law __________?', 'multiple_choice', 'Treaties', 'Customs', 'Trade mark', 'General principles', 'C', 'Trademark is a domestic legal concept, not a source of international law.'),
    (v_course_id, 'General principles of ____ serve as a source of international law.', 'multiple_choice', 'Politics', 'Law', 'Economics', 'Diplomacy', 'B', 'General principles of law recognized by civilized nations are international law sources.'),
    (v_course_id, 'Which of the following is not approach to the study of International Relaltion __________?', 'multiple_choice', 'Realist approach', 'Liberal approach', 'Justice approach', 'Constructivist approach', 'C', 'Justice approach is not a mainstream theoretical approach in IR.'),
    (v_course_id, '_____is a policy of keeping out of alliances in general and military pacts in particular.', 'multiple_choice', 'Alignment', 'Non-alignment', 'Neutrality', 'Isolationism', 'B', 'Non-alignment involves avoiding military alliances and blocs.'),
    (v_course_id, 'A non-aligned ____ can participate actively in world affairs under certain circumstances.', 'multiple_choice', 'Organization', 'State', 'Individual', 'Corporation', 'B', 'Non-aligned states can still engage actively in international diplomacy.'),
    (v_course_id, 'All are types of national interest except', 'multiple_choice', 'Primary interests', 'Permanent interests', 'Personal interest', 'Variable interests', 'C', 'Personal interest refers to individual, not national, concerns.'),
    (v_course_id, '________refer to the relatively constant and long term interests of the state.', 'multiple_choice', 'Temporary interests', 'Permanent interests', 'Secondary interests', 'Variable interests', 'B', 'Permanent interests represent enduring state objectives.'),
    (v_course_id, '________describes national interest as an interest that the states seek to protect or achieve in relation to each other.', 'multiple_choice', 'Morgenthau', 'Dyke', 'Claude', 'Aron', 'B', 'Van Dyke provided this relational definition of national interest.'),
    (v_course_id, 'According to Morgenthau ______is "an actual state of affairs in which power is distributed among several nations with approximate equality".', 'multiple_choice', 'Hegemony', 'Balance of power', 'Polarity', 'Alliance', 'B', 'Morgenthau defined balance of power as approximate equality among major powers.'),
    (v_course_id, 'Modern_______ began in Renaissance Italy.', 'multiple_choice', 'Warfare', 'Diplomacy', 'Trade', 'Law', 'B', 'Modern diplomatic practices originated in Renaissance Italian city-states.'),
    (v_course_id, '________ is one of the types of diplomacy.', 'multiple_choice', 'Military diplomacy', 'Democratic diplomacy', 'Economic diplomacy', 'Cultural diplomacy', 'B', 'Democratic diplomacy involves openness and public participation.'),
    (v_course_id, '_______ are the representatives of their governments in the international system.', 'multiple_choice', 'Soldiers', 'Diplomats', 'Businessmen', 'Journalists', 'B', 'Diplomats officially represent states in international relations.'),
    (v_course_id, '________lubricates the international system and can be use to advance the interest of all actors, state and non-state', 'multiple_choice', 'War', 'Diplomacy', 'Trade', 'Propaganda', 'B', 'Diplomacy facilitates smooth international interactions.'),
    (v_course_id, '______offers a theoretical framework to explain the incidence of wars in the international system', 'multiple_choice', 'Liberal theory', 'Power theory', 'Constructivist theory', 'Critical theory', 'B', 'Power transition theory explains war occurrence through power distributions.'),
    (v_course_id, 'Power is the central organising principle of ____causation', 'multiple_choice', 'Peace', 'War', 'Trade', 'Alliance', 'B', 'Power considerations are central to explanations of war causation.'),
    (v_course_id, 'In International relation Quincy Wright (1941: 144) describes power as being essentially a ______', 'multiple_choice', 'Function of state politics', 'Military capability', 'Economic capacity', 'Cultural influence', 'A', 'Wright conceptualized power as fundamentally political in nature.'),
    (v_course_id, 'The field of international relations concerns the relationships among the various _______of the world.', 'multiple_choice', 'Cultures', 'Governments', 'Economies', 'Societies', 'B', 'IR focuses on inter-governmental relationships.'),
    (v_course_id, 'Whether big or small, rich or poor, powerful or weak, every nation depends on other_____', 'multiple_choice', 'Institutions', 'Nations', 'Corporations', 'Organizations', 'B', 'Interdependence characterizes modern international relations.'),
    (v_course_id, 'Different scholars view international relations as a mix of conflict and _____in relationships among nations.', 'multiple_choice', 'Competition', 'Cooperation', 'Hostility', 'Indifference', 'B', 'IR involves both conflictual and cooperative interactions.'),
    (v_course_id, 'Hedley Bull has divided the various approaches for the study of international policy into two categories which include:', 'multiple_choice', 'Realist and liberal approaches', 'Classical approach and scientific approach', 'Traditional and modern approaches', 'Theoretical and practical approaches', 'B', 'Bull distinguished between classical and scientific approaches.'),
    (v_course_id, 'The main objective of the scholars adopting _______was to report and analyse current international problems.', 'multiple_choice', 'Scientific approach', 'Traditional approach', 'Behavioral approach', 'Critical approach', 'B', 'Traditional approach focused on current problem analysis.'),
    (v_course_id, '__________ focussed on the formal structure for the maintenance of peace and enforcement of principles of international law.', 'multiple_choice', 'Realist approach', 'Institutional approach', 'Liberal approach', 'Constructivist approach', 'B', 'Institutional approach emphasizes international organizations and law.'),
    (v_course_id, 'Scientific approach lays more emphasis on the _____rather than the subject matter.', 'multiple_choice', 'Theories', 'Methods of study', 'Historical context', 'Policy implications', 'B', 'Scientific approach prioritizes methodological rigor.'),
    (v_course_id, 'Which of the following is not the characteristic of state actors?', 'multiple_choice', 'Sovereignty', 'Territory', 'Violence', 'Population', 'C', 'Violence is not a defining characteristic of state actors.'),
    (v_course_id, 'In Morgenthau''s view, the obvious measure of a nation''s power is in the________', 'multiple_choice', 'Economic output', 'Military strength', 'Cultural influence', 'Diplomatic recognition', 'B', 'Morgenthau considered military capability the most visible power indicator.'),
    (v_course_id, 'Scholars of international relations often disagree over how to classify ________in world politics', 'multiple_choice', 'State actors', 'Non-state actors', 'Great powers', 'International organizations', 'B', 'Non-state actor classification remains contested in IR theory.'),
    (v_course_id, 'A_______, according to Waltz, is composed of a structure and interacting units', 'multiple_choice', 'State', 'System', 'Organization', 'Alliance', 'B', 'Waltz defined international systems as having structure and interacting units.'),
    (v_course_id, 'The ______ has a multiplicity of actors grouped broadly into two categories, namely; states and non-state actors.', 'multiple_choice', 'Domestic system', 'International system', 'Economic system', 'Social system', 'B', 'The international system includes diverse state and non-state actors.'),
    (v_course_id, 'The capacity and capability of state actors can be measured through the following except.', 'multiple_choice', 'Economic strength', 'Military power', 'Legal justification', 'Political stability', 'C', 'Legal justification is not a standard measure of state capacity.'),
    (v_course_id, 'The rules of interaction in the international system may be explicit or ______', 'multiple_choice', 'Formal', 'Implicit', 'Written', 'Legal', 'B', 'International rules can be either explicit or implicit/tacit.'),
    (v_course_id, 'Systems in the International politics can be hierarchical, unipolar, multipolar or', 'multiple_choice', 'Bipolar', 'Tripolar', 'Apolar', 'Nonpolar', 'A', 'Bipolar systems feature two dominant powers.'),
    (v_course_id, 'The following are indices power except', 'multiple_choice', 'Economic capacity', 'Military strength', 'Topography', 'Political stability', 'C', 'Topography is not typically used as a power index.'),
    (v_course_id, 'A ______in international politics will squander all other sources of power', 'multiple_choice', 'Strong economy', 'Defective leadership', 'Large population', 'Advanced technology', 'B', 'Poor leadership can undermine other power resources.'),
    (v_course_id, 'When nation''s policies are seen as legitimate in the eyes of international communities will definitely enhanced its_______', 'multiple_choice', 'Hard power', 'Soft power', 'Economic power', 'Military power', 'B', 'Perceived legitimacy enhances soft power attractiveness.'),
    (v_course_id, '______is a very important concept in the study of international relations by focusing on the techniques and procedures for conducting relations among states', 'multiple_choice', 'War', 'Diplomacy', 'Trade', 'Propaganda', 'B', 'Diplomacy involves the methods and processes of international relations.'),
    (v_course_id, 'In the absence of using force, diplomacy offers the best mechanism for ameliorating conflict in the_____', 'multiple_choice', 'Domestic arena', 'International system', 'Economic sphere', 'Cultural domain', 'B', 'Diplomacy provides peaceful conflict resolution mechanisms internationally.'),
    (v_course_id, 'The diplomatic hierarchy consisted of the following representatives except', 'multiple_choice', 'Ambassadors', 'Ministers', 'Justice', 'Chargé d''affaires', 'C', 'Justice is not a diplomatic rank or position.'),
    (v_course_id, 'The ambassador who was senior in terms of length of service in a country should be _____in that country.', 'multiple_choice', 'Doyen or dean of the diplomatic corps', 'Chief of mission', 'Senior diplomat', 'Head of delegation', 'A', 'The longest-serving ambassador becomes doyen/dean of diplomatic corps.'),
    (v_course_id, 'In international politics ______do not play a role in issues in which states can realise their interests directly through unilateral applications of leverage.', 'multiple_choice', 'States', 'Regimes', 'Corporations', 'NGOs', 'B', 'Regimes are less relevant when states can achieve goals unilaterally.'),
    (v_course_id, 'There are only ____ levels of analysis in international politics.', 'multiple_choice', '2', '3', '4', '5', 'B', 'The three levels are individual, state, and international system.'),
    (v_course_id, 'The ______specify the physical capability of an actor to carry out given classes of actions in specified settings', 'multiple_choice', 'Intent variables', 'Capability variables', 'Context variables', 'Motivation variables', 'B', 'Capability variables measure actual capacity for action.'),
    (v_course_id, '_______was developed by mathematicians and economists who were particularly concerned with political phenomena', 'multiple_choice', 'Systems theory', 'Game theory', 'Decision theory', 'Rational choice theory', 'B', 'Game theory emerged from mathematics and economics applied to politics.');
